import { createClient } from '@hey-api/client-fetch';

export const client = createClient({
    baseUrl: 'http://192.168.0.4:3000',
});

// -- Types (mirror of `openapi.json` #/components/schemas) --------------------

export interface CheckUpdateResponse {
    available: boolean;
    version: string | null;
    url: string | null;
}

export interface HealthResponse {
    ok: boolean;
}

// -- Services (one function per endpoint) ------------------------------------

export interface CheckUpdateParams {
    query?: {
        current?: string;
        app?: 'customer' | 'worker' | string;
        channel?: string;
    };
}

export async function checkUpdate(
    options: CheckUpdateParams = {},
): Promise<CheckUpdateResponse> {
    const { data, error } = await client.get<CheckUpdateResponse>({
        url: '/api/check-update',
        query: options.query,
    });
    if (error) throw new Error(String(error));
    return data as CheckUpdateResponse;
}

export async function health(): Promise<HealthResponse> {
    const { data, error } = await client.get<HealthResponse>({ url: '/health' });
    if (error) throw new Error(String(error));
    return data as HealthResponse;
}
